define("local_zoomattendance/confirmaction",["jquery","core/notification"],(function($,Notification){function init(){$(document).on("submit","form.lzs-confirm",(function(e){var form=this;if(form.getAttribute("data-lzs-confirmed")==="1"){return true}e.preventDefault();var title=form.getAttribute("data-confirm-title")||"";var body=form.getAttribute("data-confirm-body")||"";var yes=form.getAttribute("data-confirm-yes")||"";var no=form.getAttribute("data-confirm-no")||"";Notification.saveCancel(title,body,yes,(function(){form.setAttribute("data-lzs-confirmed","1");form.submit()}),no);return false}))}return{init:init}}));
